/*!
 * \file ai_infra_matmul_tiling.cc
 * \brief
 */
#include "ai_infra_matmul_tiling.h"

#include <type_traits>

#include "../../../common/inc/op_host/op_cache_tiling.h"
#include "ai_infra_matmul_base_tiling.h"
#include "ai_infra_matmul_compile_info.h"
#include "ai_infra_matmul_simplifiedkey.h"
#include "ai_infra_matmul_platform_common.h"
#include "register/op_def_registry.h"
#include "../../../common/inc/op_host/tiling_templates_registry.h"

using namespace optiling::ai_infra_matmul;
using Ops::NN::TilingPrepareForOpCache;
using Ops::NN::Optiling::TilingRegistry;

namespace {
static const size_t DEST_MAX = 100;
static const size_t MAX_LEN_SIMPLIFIED_KEY = 256;
static const int32_t INPUT0_INDEX = 0;
static const int32_t INPUT1_INDEX = 1;
static const int32_t BIAS_INDEX = 2;
} // namespace

namespace optiling {

REGISTER_TILING_TEMPLATE("AiInfraMatmul", AiInfraMatmulBaseTiling, 0);

static ge::graphStatus AiInfraMatmulTilingFunc(gert::TilingContext *context)
{
    OP_TILING_CHECK(context == nullptr, CUBE_INNER_ERR_REPORT("AiInfraMatmul", "context is null"),
                    return ge::GRAPH_FAILED);
    return TilingRegistry::GetInstance().DoTilingImpl(context);
}

static ge::graphStatus TilingPrepareForAiInfraMatmul(gert::TilingParseContext *context)
{
    OP_TILING_CHECK(context == nullptr, CUBE_INNER_ERR_REPORT("AiInfraMatmul", "context is null"),
                    return ge::GRAPH_FAILED);
    fe::PlatFormInfos *platformInfo = context->GetPlatformInfo();
    OP_TILING_CHECK(platformInfo == nullptr, CUBE_INNER_ERR_REPORT(context->GetNodeName(), "platformInfoPtr is null"),
                    return ge::GRAPH_FAILED);

    auto compileInfoPtr = context->GetCompiledInfo<AiInfraMatmulCompileInfo>();
    OP_TILING_CHECK(compileInfoPtr == nullptr, CUBE_INNER_ERR_REPORT(context->GetNodeName(), "compileInfoPtr is null"),
                    return ge::GRAPH_FAILED);
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
    platformInfo->GetPlatformRes("version", "SoC_version", compileInfoPtr->socVersionStr);
    std::string val;
    std::string dataMoveL12Bt;
    platformInfo->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_fix_pipe_l0c2out", val);
    platformInfo->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_data_move_l12bt", dataMoveL12Bt);
    compileInfoPtr->supportL0c2out = !val.empty();
    compileInfoPtr->supportL12BtBf16 = (dataMoveL12Bt.find("bf16") != std::string::npos);
    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
    compileInfoPtr->socVersion = ascendcPlatform.GetSocVersion();
    compileInfoPtr->npuArch = ascendcPlatform.GetCurNpuArch();
    compileInfoPtr->btSize = compileInfoPtr->supportL0c2out ? 1024UL : 0UL;                      // 1024 is btSize
    compileInfoPtr->btSize = compileInfoPtr->supportL12BtBf16 ? 4096UL : compileInfoPtr->btSize; // 4096 is btSize
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, compileInfoPtr->l0ASize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, compileInfoPtr->l0BSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0CSize);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, compileInfoPtr->l2Size);

    if (!TilingPrepareForOpCache(context)) {
        OP_LOGE(context->GetNodeName(), "TilingPrepareForOpCache fail");
        return ge::GRAPH_FAILED;
    }
    OP_LOGI(context->GetNodeName(),
            "parse compile info success soc:%d, npu arch: %u, l1Size:%lu, l2Size:%lu, coreNum:%lu, supportL0c2out:%d, "
            "supportL12BtBf16:%d",
            static_cast<int>(compileInfoPtr->socVersion), compileInfoPtr->npuArch, compileInfoPtr->l1Size,
            compileInfoPtr->l2Size, compileInfoPtr->aicNum, compileInfoPtr->supportL0c2out,
            compileInfoPtr->supportL12BtBf16);
    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(AiInfraMatmul)
    .Tiling(AiInfraMatmulTilingFunc)
    .TilingParse<AiInfraMatmulCompileInfo>(TilingPrepareForAiInfraMatmul)
    .GenSimplifiedKey(GenSimplifiedKey);
} // namespace optiling

