12	 * \file hash.cpp
13	 * \brief function of hash
14	 */
15	#include "hash.h"
16	
17	namespace Ops {
18	namespace NN {
19	static constexpr uint32_t kRolScrambleLeft = 15;
20	static constexpr uint32_t kRolScrambleRight = 17;
21	static constexpr uint32_t kRolBodyLeft = 13;
22	static constexpr uint32_t kRolBodyRight = 19;
23	static constexpr uint32_t kChunkOffset = 5;
24	static constexpr uint32_t kRolTailLeft = 8;
25	static constexpr uint32_t kRolTailRight = 13;
26	static constexpr uint32_t kReadSize = 16;
27	static constexpr int32_t kMaxTilingCacheEntryNum = 500;
28	
29	static inline uint32_t MurmurScramble(uint32_t key)
30	{
31	  key *= static_cast<uint32_t>(0xcc9e2d51);
32	  key = (key << kRolScrambleLeft) | (key >> kRolScrambleRight);
33	  key *= static_cast<uint32_t>(0x1b873593);
34	  return key;
35	}
36	
37	uint32_t MurmurHash(const void *src, uint32_t len, uint32_t seed)
38	{
39	  const uint32_t *key = static_cast<const uint32_t *>(src);
40	  uint32_t hash_key = seed;
41	  uint32_t tmp_key;
42	  // Read in blocks of 4
43	  for (uint32_t i = len >> 2UL; i > 0UL; i--) {
44	    // Get a source of differing results across endiannesses.
45	    tmp_key = *key;
46	    key++;
47	    hash_key ^= MurmurScramble(tmp_key);
48	    hash_key = (hash_key << kRolBodyLeft) | (hash_key >> kRolBodyRight);
49	    hash_key = hash_key * kChunkOffset + 0xe6546b64;
50	  }
51	  // Process the rest
52	  const uint8_t *rest_key = static_cast<const uint8_t *>(src);
53	  tmp_key = 0U;
54	  for (uint32_t i = len & 3U; i != 0U; i--) {
55	    tmp_key <<= kRolTailLeft;
56	    tmp_key |= rest_key[i - 1U];
57	  }
58	  hash_key ^= MurmurScramble(tmp_key);
59	  // Finalize
60	  hash_key ^= len;
61	  hash_key ^= hash_key >> kReadSize;
62	  hash_key *= static_cast<uint32_t>(0x85ebca6b);
63	  hash_key ^= hash_key >> kRolTailRight;
64	  hash_key *= static_cast<uint32_t>(0xc2b2ae35);
65	  hash_key ^= hash_key >> kReadSize;
66	  return hash_key;
67	}
68	}  // namespace NN
69	}  // namespace Ops

