60	class TilingBaseClass {
61	public:
62	    explicit TilingBaseClass(gert::TilingContext* context) : context_(context)
63	    {}
64	
65	    virtual ~TilingBaseClass() = default;
66	
67	    // Tiling执行框架
68	    //     1、GRAPH_SUCCESS: 成功，并且不需要继续执行后续Tiling类的实现
69	    //     2、GRAPH_FAILED: 失败，中止整个Tiling流程
70	    //     3、GRAPH_PARAM_INVALID: 本类不支持，需要继续往下执行其他Tiling类的实现
71	    ge::graphStatus DoTiling()
72	    {
73	        auto ret = GetShapeAttrsInfo();
74	        if (ret != ge::GRAPH_SUCCESS) {
75	            return ret;
76	        }
77	        ret = GetPlatformInfo();
78	        if (ret != ge::GRAPH_SUCCESS) {
79	            return ret;
80	        }
81	        if (!IsCapable()) {
82	            return ge::GRAPH_PARAM_INVALID;
83	        }
84	        ret = DoOpTiling();
85	        if (ret != ge::GRAPH_SUCCESS) {
86	            return ret;
87	        }
88	        ret = DoLibApiTiling();
89	        if (ret != ge::GRAPH_SUCCESS) {
90	            return ret;
91	        }
92	        ret = GetWorkspaceSize();
93	        if (ret != ge::GRAPH_SUCCESS) {
94	            return ret;
95	        }
96	        ret = PostTiling();
97	        if (ret != ge::GRAPH_SUCCESS) {
98	            return ret;
99	        }
100	        context_->SetTilingKey(GetTilingKey());
101	        DumpTilingInfo();
102	        return ge::GRAPH_SUCCESS;
103	    }
104	
105	    // 更新 context
106	    virtual void Reset(gert::TilingContext* context)
107	    {
108	        context_ = context;
109	    }
110	
111	protected:
112	    virtual bool IsCapable() = 0;
113	    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
114	    virtual ge::graphStatus GetPlatformInfo() = 0;
115	    // 2、获取INPUT/OUTPUT/ATTR信息
116	    virtual ge::graphStatus GetShapeAttrsInfo() = 0;
117	    // 3、计算数据切分TilingData
118	    virtual ge::graphStatus DoOpTiling() = 0;
119	    // 4、计算高阶API的TilingData
120	    virtual ge::graphStatus DoLibApiTiling() = 0;
121	    // 5、计算TilingKey
122	    [[nodiscard]] virtual uint64_t GetTilingKey() const = 0;
123	    // 6、计算Workspace 大小
124	    virtual ge::graphStatus GetWorkspaceSize() = 0;
125	    // 7、保存Tiling数据
126	    virtual ge::graphStatus PostTiling() = 0;
127	    // 8、Dump Tiling数据
128	    virtual void DumpTilingInfo()
129	    {
130	        int32_t enable = AlogCheckDebugLevel(static_cast<int32_t>(OP), DLOG_DEBUG);
131	        if (enable != 1) {
132	            return;
133	        }
134	        auto buf = (uint32_t*)context_->GetRawTilingData()->GetData();
135	        auto bufLen = context_->GetRawTilingData()->GetDataSize();
136	        std::ostringstream oss;
137	        oss << "Start to dump tiling info. tilingkey:" << context_->GetTilingKey() << ", tiling data size:" << bufLen
138	            << ", content:";
139	        for (size_t i = 0; i < bufLen / sizeof(uint32_t); i++) {
140	            oss << *(buf + i) << ",";
141	            if (oss.str().length() > 640) { // Split according to 640 to avoid truncation
142	                OP_LOGD(context_, "%s", oss.str().c_str());
143	                oss.str("");
144	            }
145	        }
146	        OP_LOGD(context_, "%s", oss.str().c_str());
147	    }
148	
149	    static uint32_t CalcTschBlockDim(uint32_t sliceNum, uint32_t aicCoreNum, uint32_t aivCoreNum)
150	    {
151	        uint32_t ration;
152	        if (aicCoreNum == 0 || aivCoreNum == 0 || aicCoreNum > aivCoreNum) {
153	            return sliceNum;
154	        }
155	        ration = aivCoreNum / aicCoreNum;
156	        return (sliceNum + (ration - 1)) / ration;
157	    }
158	
159	    template <typename T>
160	    [[nodiscard]] std::string GetShapeDebugStr(const T& shape) const
161	    {
162	        std::ostringstream oss;
163	        oss << "[";
164	        if (shape.GetDimNum() > 0) {
165	            for (size_t i = 0; i < shape.GetDimNum() - 1; ++i) {
166	                oss << shape.GetDim(i) << ", ";
167	            }
168	            oss << shape.GetDim(shape.GetDimNum() - 1);
169	        }
170	        oss << "]";
171	        return oss.str();
172	    }
173	
174	    [[nodiscard]] std::string GetTensorDebugStr(
175	        const gert::StorageShape* shape, const gert::CompileTimeTensorDesc* tensor) const
176	    {
177	        if (shape == nullptr || tensor == nullptr) {
178	            return "nil ";
179	        }
180	        std::ostringstream oss;
181	        oss << "(dtype: " << ge::TypeUtils::DataTypeToSerialString(tensor->GetDataType()) << "),";
182	        oss << "(shape:" << GetShapeDebugStr(shape->GetStorageShape()) << "),";
183	        oss << "(ori_shape:" << GetShapeDebugStr(shape->GetOriginShape()) << "),";
