aclnnStatus aclnnAiInfraMatmulGetWorkspaceSize(const aclTensor *self, const aclTensor *mat2, aclTensor *out,
                                               int8_t cubeMathType, size_t *workspaceSize, aclOpExecutor **executor)
{
    L2_DFX_PHASE_1(aclnnAiInfraMatmul, DFX_IN(self, mat2, cubeMathType), DFX_OUT(out));

    // 入参检查
    auto ret = CheckInputParams(self, mat2, out, cubeMathType);
    CHECK_RET(ret == ACLNN_SUCCESS, ret);

    // 固定写法，创建OpExecutor
    auto uniqueExecutor = CREATE_EXECUTOR();
    CHECK_RET(uniqueExecutor.get() != nullptr, ACLNN_ERR_INNER_CREATE_EXECUTOR);

    // 空tensor处理
    if (out->IsEmpty() && (self->IsEmpty() || mat2->IsEmpty())) {
        OP_LOGI("Returning an empty tensor without actually doing calculation.");
        *workspaceSize = 0;
        uniqueExecutor.ReleaseTo(executor);
        return ACLNN_SUCCESS;
    }

    // 构建matmul计算图
    std::shared_ptr<MatmulGraphImpl> matmulGraph =
        CreateMatmulGraphImpl(self, mat2, out, cubeMathType, uniqueExecutor.get());
    CHECK_RET(matmulGraph != nullptr, ACLNN_ERR_INNER_NULLPTR);

    // 执行计算图
    auto executeStatus = matmulGraph->Execute();
    CHECK_RET(executeStatus == ACLNN_SUCCESS, executeStatus);

    // 获取workspace
    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
    uniqueExecutor.ReleaseTo(executor);

    return ACLNN_SUCCESS;
}

